    export const getSessionRecordsListUrl = (centerId: string,
    params: SessionRecordsListParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/centers/${centerId}/session-records?${stringifiedParams}` : `/v1/centers/${centerId}/session-records`
}

